/**
 * Anatomical face map: a reference face with the facial muscles as Blender-rendered layers (src/ui/anatomy), each
 * tinted by a 0–1 value (stronger colour = worse). The affected side carries the values; the healthy side shows the
 * same muscles in a neutral tone for reference. Muscles the app does not measure on their own (`inferred`) are drawn
 * paler with a dashed outline, carrying the value of the movement they share a nerve branch and pull with.
 * Mirror view (patient right on the right), like the wireframe view. No photograph is used.
 */
import { useMemo } from 'preact/hooks';
import type { CouplingRegion, Side } from '../../core';
import { refFace } from '../anatomy/refFace';
import { ANATOMY_NAME, ANATOMY_ORDER, type Anatomy } from '../anatomy/sheets';

export { ANATOMY_NAME, type Anatomy };
export type AnatomyValues = Partial<Record<Anatomy, number>>;

const TONE = { synk: [0.898, 0.282, 0.302], weak: [0.243, 0.388, 0.867] } as const;
const NEUTRAL = [0.94, 0.74, 0.7] as const;
let seq = 0;

/** feColorMatrix tinting a grey layer: colour × (a·L + b), alpha × opacity. Stronger values keep more shading. */
function tint([r, g, b]: readonly number[], v: number, opacity: number): string {
  const [a, o] = [0.45 + 0.35 * v, 0.6 - 0.3 * v];
  const k = (c: number, s: number) => (c * s).toFixed(3);
  return [`${k(r!, a)} 0 0 0 ${k(r!, o)}`, `0 ${k(g!, a)} 0 0 ${k(g!, o)}`, `0 0 ${k(b!, a)} 0 ${k(b!, o)}`, `0 0 0 ${opacity.toFixed(2)} 0`].join(' ');
}

export function AnatomyFace({
  affectedSide,
  values,
  inferred = {},
  tone,
  selected = [],
  onSelect,
}: {
  affectedSide: Side;
  /** Measured muscles. */
  values: AnatomyValues;
  /** Muscles not measured on their own: value of the related movement (drawn paler, dashed). */
  inferred?: AnatomyValues;
  /** synk = warm, weak = cool. */
  tone: 'synk' | 'weak';
  selected?: readonly Anatomy[];
  onSelect?: (a: Anatomy) => void;
}) {
  const R = refFace();
  const uid = useMemo(() => `am${++seq}`, []);
  const [vx, vy, vw, vh] = R.viewBox;
  const u = R.unit;
  const affOnRight = affectedSide === 'right';
  const fs = 0.13 * u;
  const layers = (['left', 'right'] as const).flatMap((side) =>
    ANATOMY_ORDER.map((a) => {
      const aff = side === affectedSide;
      const v = aff ? Math.max(0, Math.min(1, values[a] ?? 0.55 * (inferred[a] ?? 0))) : 0;
      const c = NEUTRAL.map((n, k) => n + (TONE[tone][k]! - n) * v);
      return { id: `${uid}-${side}-${a}`, matrix: tint(c, v, aff ? 0.7 + 0.28 * v : 0.42), L: R.muscles[side][a] };
    }),
  );
  return (
    <svg
      viewBox={`${vx} ${vy} ${vw} ${vh}`}
      style={{ width: '100%', maxWidth: '340px', display: 'block', margin: '0 auto' }}
      role="img"
      aria-label="얼굴 근육 지도"
    >
      <defs>
        <radialGradient id={`${uid}-skin`} cx="50%" cy="42%" r="62%">
          <stop offset="0" stop-color="#FCE5D2" />
          <stop offset="1" stop-color="#F0C6A8" />
        </radialGradient>
        <linearGradient id={`${uid}-hair`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stop-color="#57433a" />
          <stop offset="0.5" stop-color="#3B2F2F" />
          <stop offset="1" stop-color="#2e2422" />
        </linearGradient>
        <radialGradient id={`${uid}-iris`}>
          <stop offset="0.35" stop-color="#3a2a22" />
          <stop offset="1" stop-color="#7a5a45" />
        </radialGradient>
        {layers.map((l) => (
          <filter id={l.id} color-interpolation-filters="sRGB">
            <feColorMatrix type="matrix" values={l.matrix} />
          </filter>
        ))}
        {R.eyes.map((e, k) => (
          <clipPath id={`${uid}-eye${k}`}>
            <path d={e.almond} />
          </clipPath>
        ))}
      </defs>
      <g transform={`matrix(-1 0 0 1 ${2 * R.cx} 0)`}>
        <path d={R.neck} fill="#EDBFA2" />
        <ellipse cx={R.chin.x} cy={R.chin.y} rx={0.42 * u} ry={0.12 * u} fill="#dca58a" opacity="0.55" />
        <path d={R.skin} fill={`url(#${uid}-skin)`} />
        {layers.map((l) => (
          <image href={l.L.href} x={l.L.box[0]} y={l.L.box[1]} width={l.L.box[2]} height={l.L.box[3]} filter={`url(#${l.id})`} />
        ))}
        <path d={R.hair} fill={`url(#${uid}-hair)`} />
        {R.brows.map((d) => (
          <path d={d} fill="#4a372c" opacity="0.92" />
        ))}
        {R.eyes.map((e, k) => (
          <g>
            <path d={e.almond} fill="#fff" />
            <g clip-path={`url(#${uid}-eye${k})`}>
              <circle cx={e.iris.x} cy={e.iris.y} r={0.1 * u} fill={`url(#${uid}-iris)`} />
              <circle cx={e.iris.x} cy={e.iris.y} r={0.042 * u} fill="#1d1411" />
              <circle cx={e.iris.x + 0.03 * u} cy={e.iris.y - 0.03 * u} r={0.014 * u} fill="#fff" />
            </g>
            <path d={e.crease} fill="none" stroke="#c9957a" stroke-width={0.009 * u} stroke-linecap="round" />
            <path d={e.lower} fill="none" stroke="#b98a72" stroke-width={0.01 * u} stroke-linecap="round" />
            <path d={e.lid} fill="none" stroke="#3a2a22" stroke-width={0.024 * u} stroke-linecap="round" />
          </g>
        ))}
        {R.nose.side.map((d) => (
          <path d={d} fill="none" stroke="#d9a787" stroke-width={0.012 * u} stroke-linecap="round" opacity="0.35" />
        ))}
        {R.nose.ala.map((d) => (
          <path d={d} fill="none" stroke="#b97c62" stroke-width={0.016 * u} stroke-linecap="round" />
        ))}
        {R.nose.nostrils.map((n) => (
          <ellipse cx={n.c.x} cy={n.c.y} rx={0.05 * u} ry={0.022 * u} transform={`rotate(${n.rot.toFixed(1)} ${n.c.x} ${n.c.y})`} fill="#9c604c" opacity="0.75" />
        ))}
        <path d={R.lips.upper} fill="#D98B86" />
        <path d={R.lips.lower} fill="#E39A93" />
        <path d={R.lips.seam} fill="none" stroke="#a9554f" stroke-width={0.014 * u} stroke-linecap="round" />
        <g fill="none" stroke-linejoin="round" pointer-events="none">
          {(Object.keys(inferred) as Anatomy[])
            .filter((a) => !selected.includes(a))
            .map((a) => (
              <path d={R.muscles[affectedSide][a].outline} stroke="#6b5a55" stroke-width={0.006 * u} stroke-dasharray={`${0.022 * u} ${0.016 * u}`} stroke-opacity="0.75" />
            ))}
          {selected.map((a) => (
            <g>
              <path d={R.muscles[affectedSide][a].outline} stroke="#fff" stroke-width={0.02 * u} stroke-opacity="0.85" />
              <path d={R.muscles[affectedSide][a].outline} stroke="#1b1b1b" stroke-width={0.008 * u} stroke-dasharray={a in inferred ? `${0.022 * u} ${0.016 * u}` : undefined} />
            </g>
          ))}
        </g>
        {onSelect &&
          ANATOMY_ORDER.map((a) => (
            <path d={R.muscles[affectedSide][a].outline} fill-rule="evenodd" fill="#000" fill-opacity="0" style={{ cursor: 'pointer' }} onClick={() => onSelect(a)}>
              <title>{ANATOMY_NAME[a]}</title>
            </path>
          ))}
      </g>
      <text x={affOnRight ? vx + vw - 0.08 * u : vx + 0.08 * u} y={vy + 1.3 * fs} text-anchor={affOnRight ? 'end' : 'start'} font-size={fs} fill="var(--ink-2)" font-weight="700">
        마비 쪽
      </text>
      <text x={affOnRight ? vx + 0.08 * u : vx + vw - 0.08 * u} y={vy + 1.3 * fs} text-anchor={affOnRight ? 'start' : 'end'} font-size={fs} fill="var(--muted)">
        건강한 쪽
      </text>
    </svg>
  );
}

/** Coupling regions (synkinesis) drawn on the muscle that moves them. */
export type MapRegion = CouplingRegion | 'lowerLip';
export type RegionValues = Partial<Record<MapRegion, number>>;
export const REGION_NAME: Record<MapRegion, string> = {
  brow: '눈썹·이마',
  eye: '눈',
  midface: '코·볼',
  upperLip: '윗입술',
  mouth: '입꼬리',
  lowerLip: '아랫입술',
};
/** Muscles moving each region: the one the map colours, and the others acting there (paler, dashed). */
const REGION_MUSCLES: Record<MapRegion, { main: readonly Anatomy[]; related: readonly Anatomy[] }> = {
  brow: { main: ['frontalis'], related: ['corrugator'] },
  eye: { main: ['orbicularisOculi'], related: [] },
  midface: { main: ['llsan'], related: [] },
  upperLip: { main: ['lls', 'zygMinor'], related: [] },
  mouth: { main: ['zygMajor'], related: ['lao', 'risorius', 'buccinator'] },
  lowerLip: { main: ['depressors'], related: ['platysma'] },
};

export function FaceMap({
  affectedSide,
  values,
  tone,
  selected,
  onSelect,
}: {
  affectedSide: Side;
  values: RegionValues;
  tone: 'synk' | 'weak';
  selected?: MapRegion | null;
  onSelect?: (r: MapRegion) => void;
}) {
  const av: AnatomyValues = {};
  const inf: AnatomyValues = {};
  for (const [r, m] of Object.entries(REGION_MUSCLES) as [MapRegion, (typeof REGION_MUSCLES)[MapRegion]][]) {
    const v = values[r] ?? 0;
    for (const a of m.main) av[a] = Math.max(av[a] ?? 0, v);
    for (const a of m.related) inf[a] = Math.max(inf[a] ?? 0, v);
  }
  const regionOf = (a: Anatomy) =>
    (Object.keys(REGION_MUSCLES) as MapRegion[]).find((r) => REGION_MUSCLES[r].main.includes(a) || REGION_MUSCLES[r].related.includes(a));
  return (
    <AnatomyFace
      affectedSide={affectedSide}
      values={av}
      inferred={inf}
      tone={tone}
      selected={selected ? [...REGION_MUSCLES[selected].main, ...REGION_MUSCLES[selected].related] : []}
      onSelect={
        onSelect
          ? (a) => {
              const r = regionOf(a);
              if (r) onSelect(r);
            }
          : undefined
      }
    />
  );
}
