/**
 * Reference face of the anatomy map: the CC0 character the muscle layers were rendered on. face.json holds its
 * landmarks from the app's own model, in pixels of the 800 × 1000 render; everything here is in those pixels, so
 * the drawn face, the Blender layers (layers.json boxes) and the muscle outlines line up exactly. The face is drawn
 * in the visual language of the rehab illustrations (skin gradient, bob, soft features).
 */
import { faceFrame, toFaceCoords, type Vec2 } from '../../core';
import face from './face.json';
import boxes from './layers.json';
import { ANATOMY_ORDER, outline, sideSheets, type Anatomy } from './sheets';

const URLS = import.meta.glob('./layers/*.webp', { eager: true, query: '?url', import: 'default' }) as Record<string, string>;

export interface MuscleLayer {
  href: string;
  box: readonly [number, number, number, number];
  /** Outline for taps and the selection ring (evenodd). */
  outline: string;
}

export interface RefFace {
  /** Mirror axis (x of the face's midline). */
  cx: number;
  /** Pixels per IPD. */
  unit: number;
  /** Under the chin (neck shadow). */
  chin: Vec2;
  viewBox: readonly [number, number, number, number];
  neck: string;
  skin: string;
  hair: string;
  brows: string[];
  eyes: { almond: string; iris: Vec2; lid: string; lower: string; crease: string }[];
  nose: { side: string[]; ala: string[]; nostrils: { c: Vec2; rot: number }[] };
  lips: { upper: string; lower: string; seam: string };
  muscles: Record<'left' | 'right', Record<Anatomy, MuscleLayer>>;
}

const f1 = (n: number) => n.toFixed(1);

/** Catmull-Rom through the points as cubic Béziers (as in the rehab face). */
export function smooth(ps: readonly Vec2[], closed: boolean): string {
  const n = ps.length;
  const get = (i: number) => (closed ? ps[(i + n) % n]! : ps[Math.max(0, Math.min(n - 1, i))]!);
  let d = `M${f1(ps[0]!.x)},${f1(ps[0]!.y)}`;
  for (let i = 0; i < (closed ? n : n - 1); i++) {
    const [p0, p1, p2, p3] = [get(i - 1), get(i), get(i + 1), get(i + 2)];
    d += ` C${f1(p1.x + (p2.x - p0.x) / 6)},${f1(p1.y + (p2.y - p0.y) / 6)} ${f1(p2.x - (p3.x - p1.x) / 6)},${f1(p2.y - (p3.y - p1.y) / 6)} ${f1(p2.x)},${f1(p2.y)}`;
  }
  return closed ? `${d}Z` : d;
}

const poly = (ps: readonly Vec2[]) => ps.map((p, k) => `${k ? 'L' : 'M'}${f1(p.x)},${f1(p.y)}`).join('') + 'Z';

let cache: RefFace | null = null;

export function refFace(): RefFace {
  if (cache) return cache;
  const px: Vec2[] = Array.from({ length: face.points.length / 2 }, (_, i) => ({ x: face.points[2 * i]!, y: face.points[2 * i + 1]! }));
  const fr = faceFrame(px);
  const F = toFaceCoords(fr, px);
  /** Face coordinates (IPD, +x = patient left) → pixels. */
  const P = (p: Vec2): Vec2 => ({
    x: fr.origin.x + (fr.ex.x * p.x + fr.ey.x * p.y) * fr.unitPx,
    y: fr.origin.y + (fr.ex.y * p.x + fr.ey.y * p.y) * fr.unitPx,
  });
  const L = (i: number) => px[i]!;
  const both = (right: readonly [number, number][]) => {
    // Right half (outward = −x) then the mirrored left half back up: one closed outline.
    const r = right.map(([x, y]) => ({ x, y }));
    return [...r, ...[...r].reverse().map((p) => ({ x: -p.x, y: p.y }))];
  };

  // Head: jaw and chin from the face oval (162 → 152 → 389), the cranium as a dome under the hair.
  const oval = [162, 127, 234, 93, 132, 58, 172, 136, 150, 149, 176, 148, 152, 377, 400, 378, 379, 365, 397, 288, 361, 323, 454, 356, 389];
  const dome: Vec2[] = [
    { x: 1.12, y: -0.7 },
    { x: 0.95, y: -1.2 },
    { x: 0.55, y: -1.5 },
    { x: 0, y: -1.58 },
    { x: -0.55, y: -1.5 },
    { x: -0.95, y: -1.2 },
    { x: -1.12, y: -0.7 },
  ];
  const skin = smooth([...oval.map(L), ...dome.map(P)], true);
  // Bob: outer silhouette down to the jaw, curling under; the inner edge lies on the cheeks' outline (a little
  // over it, no gap) and frames the forehead above the frontalis.
  const outer: [number, number][] = [
    [-0.5, -1.6],
    [-0.9, -1.4],
    [-1.16, -1.02],
    [-1.28, -0.5],
    [-1.31, 0],
    [-1.28, 0.5],
    [-1.22, 0.88],
    [-1.12, 1.14],
  ];
  const cheek = [58, 132, 93, 234, 127, 162, 21].map((i) => ({ x: F[i]!.x + 0.03, y: F[i]!.y }));
  const brow: [number, number][] = [
    [-0.97, -0.68],
    [-0.8, -1.0],
    [-0.46, -1.18],
  ];
  const sideR = [...outer.map(([x, y]) => ({ x, y })), { x: -0.97, y: 1.06 }, ...cheek, ...brow.map(([x, y]) => ({ x, y }))];
  const hair = smooth([{ x: 0, y: -1.64 }, ...sideR, { x: 0, y: -1.24 }, ...[...sideR].reverse().map((p) => ({ x: -p.x, y: p.y }))].map(P), true);
  // Neck and the slope of the shoulders, as measured on the render (the platysma lies on them).
  const neck = smooth(
    both([
      [-0.6, 1.1],
      [-0.64, 1.45],
      [-0.66, 1.66],
      [-0.74, 1.8],
      [-0.9, 1.92],
      [-1.1, 2.04],
      [-1.36, 2.14],
      [-1.55, 2.2],
      [-1.6, 2.5],
    ]).map(P),
    true,
  );

  const browIdx = [
    [70, 63, 105, 66, 107, 55, 65, 52, 53, 46],
    [300, 293, 334, 296, 336, 285, 295, 282, 283, 276],
  ];
  const brows = browIdx.map((ix) => smooth(ix.map(L), true));
  const eyeIdx = [
    { c: [33, 246, 161, 160, 159, 158, 157, 173, 133, 155, 154, 153, 145, 144, 163, 7], crease: [225, 224, 223, 222, 221], iris: 468 },
    { c: [263, 466, 388, 387, 386, 385, 384, 398, 362, 382, 381, 380, 374, 373, 390, 249], crease: [445, 444, 443, 442, 441], iris: 473 },
  ];
  const eyes = eyeIdx.map((e) => {
    const c = e.c.map(L);
    const up = c.slice(0, 9);
    // Crease halfway between the upper lid and the orbit points above it.
    const crease = e.crease.map((i, k) => {
      const lid = up[1 + 2 * k] ?? up[up.length - 1]!;
      return { x: (L(i).x + lid.x) / 2, y: (L(i).y + lid.y) / 2 - 0.01 * fr.unitPx };
    });
    return { almond: smooth(c, true), iris: L(e.iris), lid: smooth(up, false), lower: smooth([...c.slice(8), c[0]!], false), crease: smooth(crease, false) };
  });
  const nose = {
    side: [
      [122, 196, 3, 51],
      [351, 419, 248, 281],
    ].map((ix) => smooth(ix.map(L), false)),
    ala: [
      [49, 102, 64, 98, 240],
      [279, 331, 294, 327, 460],
    ].map((ix) => smooth(ix.map(L), false)),
    nostrils: [
      [99, 60, 75],
      [328, 290, 305],
    ].map((ix) => {
      const c = { x: ix.reduce((s, i) => s + L(i).x, 0) / 3, y: ix.reduce((s, i) => s + L(i).y, 0) / 3 };
      const d = { x: L(ix[2]!).x - L(ix[0]!).x, y: L(ix[2]!).y - L(ix[0]!).y };
      return { c, rot: (Math.atan2(d.y, d.x) * 180) / Math.PI };
    }),
  };
  // Lips: outer contour halves closed by a single mouth line (the render's lips are slightly apart).
  const upIn = [78, 191, 80, 81, 82, 13, 312, 311, 310, 415, 308];
  const loIn = [78, 95, 88, 178, 87, 14, 317, 402, 318, 324, 308];
  const seamPts = upIn.map((i, k) => ({ x: (L(i).x + L(loIn[k]!).x) / 2, y: (L(i).y + L(loIn[k]!).y) / 2 }));
  const upperOut = [61, 185, 40, 39, 37, 0, 267, 269, 270, 409, 291].map(L);
  const lowerOut = [291, 375, 321, 405, 314, 17, 84, 181, 91, 146, 61].map(L);
  const lips = {
    upper: smooth([...upperOut, ...[...seamPts].reverse().slice(1, -1)], true),
    lower: smooth([...lowerOut, ...seamPts.slice(1, -1)], true),
    seam: smooth(seamPts, false),
  };

  const BOX: Record<string, number[]> = boxes;
  const layer = (side: 'left' | 'right', a: Anatomy, outlines: string): MuscleLayer => {
    const b = BOX[`${a}-${side}`]!;
    return { href: URLS[`./layers/${a}-${side}.webp`]!, box: [b[0]!, b[1]!, b[2]!, b[3]!], outline: outlines };
  };
  const muscles = { left: {}, right: {} } as RefFace['muscles'];
  for (const side of ['left', 'right'] as const) {
    const sheets = sideSheets(F, side);
    for (const a of ANATOMY_ORDER) muscles[side][a] = layer(side, a, sheets[a].flatMap((g) => outline(g).map((loop) => poly(loop.map(P)))).join(''));
  }

  const u = fr.unitPx;
  cache = {
    cx: fr.origin.x,
    unit: u,
    chin: P({ x: 0, y: 1.76 }),
    viewBox: [fr.origin.x - 1.4 * u, fr.origin.y - 1.7 * u, 2.8 * u, 3.88 * u],
    neck,
    skin,
    hair,
    brows,
    eyes,
    nose,
    lips,
    muscles,
  };
  return cache;
}
