/**
 * Facial muscle sheets for the anatomy map, built on face landmarks in face coordinates (IPD units, origin between
 * the pupils, +x towards the patient's left, +y towards the chin).
 *
 * Each muscle is one or more grids of fibre-aligned points: rows run from origin to insertion (straight muscles) or
 * from the inner to the outer edge (sphincters). The same grids place the Blender-rendered layers
 * (tools/blender/anatomy_layers.py) and draw the outlines the map uses for taps and selection. Origins and
 * insertions follow standard anatomy, placed from the nearest landmarks with offsets in IPD units. Only the
 * patient's right side is defined; the left is its mirror image (the map uses a symmetric reference face).
 * The muscles are those of the rehab stretch programme (src/rehab/face.ts MUSCLES), one layer each.
 */
import { CONTOURS, type Vec2 } from '../../core';
import { MUSCLES, type MuscleId } from '../../rehab/face';

export type Anatomy = MuscleId;

export const ANATOMY_NAME = Object.fromEntries(Object.entries(MUSCLES).map(([k, m]) => [k, m.name])) as Record<Anatomy, string>;

/** Paint order, deep to superficial (the corrugator, deep to the brow muscles, last so it stays visible). */
export const ANATOMY_ORDER: readonly Anatomy[] = [
  'buccinator',
  'lao',
  'frontalis',
  'platysma',
  'depressors',
  'lls',
  'zygMinor',
  'llsan',
  'zygMajor',
  'risorius',
  'orbicularisOris',
  'orbicularisOculi',
  'corrugator',
];

export interface Grid {
  /** nv rows of nu points: origin → insertion, or inner → outer edge for sphincters. */
  pts: Vec2[];
  nu: number;
  nv: number;
  /** Ring closed in u (orbicularis oculi). */
  closed: boolean;
  /** The two halves meet here at the u ends (orbicularis oris): no fade there. */
  seam: boolean;
  /** Fibres run along u (sphincters) or v (straight muscles). */
  fibre: 'u' | 'v';
  /** Striations across the fibres. */
  bundles: number;
  /** Belly lift in IPD (render only). */
  thick: number;
}

const add = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x + b.x, y: a.y + b.y });
const sub = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x - b.x, y: a.y - b.y });
const mul = (a: Vec2, k: number): Vec2 => ({ x: a.x * k, y: a.y * k });
const len = (a: Vec2): number => Math.hypot(a.x, a.y);
const lerp = (a: Vec2, b: Vec2, t: number): Vec2 => ({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t });
const bez = (a: Vec2, c: Vec2, b: Vec2, t: number): Vec2 => lerp(lerp(a, c, t), lerp(c, b, t), t);

/** Points at equal arc length along a polyline (n ≥ 2). */
export function resample(ps: readonly Vec2[], n: number): Vec2[] {
  const seg = ps.slice(1).map((p, i) => len(sub(p, ps[i]!)));
  const total = seg.reduce((a, b) => a + b, 0) || 1;
  const out: Vec2[] = [];
  for (let k = 0; k < n; k++) {
    let t = (k / (n - 1)) * total;
    let i = 0;
    while (i < seg.length - 1 && t > seg[i]!) t -= seg[i++]!;
    out.push(lerp(ps[i]!, ps[i + 1] ?? ps[i]!, seg[i] ? Math.min(1, t / seg[i]!) : 0));
  }
  return out;
}

const STRIPE = 0.02; // striation spacing (IPD)
const bundlesFor = (width: number) => Math.max(3, Math.round(width / STRIPE));

function grid(rows: Vec2[][], o: Pick<Grid, 'closed' | 'seam' | 'fibre' | 'thick'>): Grid {
  const nu = rows[0]!.length;
  // Striation count across the fibres from the mean width.
  const across =
    o.fibre === 'v'
      ? rows.reduce((s, r) => s + len(sub(r[0]!, r[nu - 1]!)), 0) / rows.length
      : rows[0]!.reduce((s, _, i) => s + len(sub(rows[0]![i]!, rows[rows.length - 1]![i]!)), 0) / nu;
  return { pts: rows.flat(), nu, nv: rows.length, bundles: bundlesFor(across), ...o };
}

/** Sheet from curve A (origin) to curve B (insertion); fibres straight, or bent towards the control curve C. */
function sheet(A: readonly Vec2[], B: readonly Vec2[], nu: number, nv: number, thick: number, C?: readonly Vec2[]): Grid {
  const a = resample(A, nu);
  const b = resample(B, nu);
  const c = C && resample(C, nu);
  const rows = Array.from({ length: nv }, (_, iv) => a.map((p, i) => (c ? bez(p, c[i]!, b[i]!, iv / (nv - 1)) : lerp(p, b[i]!, iv / (nv - 1)))));
  return grid(rows, { closed: false, seam: false, fibre: 'v', thick });
}

/** Strap along the quadratic centre line a → b (control c), half width hw(t). */
function strap(a: Vec2, c: Vec2, b: Vec2, hw: (t: number) => number, nu: number, nv: number, thick: number): Grid {
  const rows = Array.from({ length: nv }, (_, iv) => {
    const t = iv / (nv - 1);
    const p = bez(a, c, b, t);
    const d = sub(lerp(c, b, t), lerp(a, c, t));
    const n = mul({ x: -d.y, y: d.x }, 1 / (len(d) || 1));
    return Array.from({ length: nu }, (_, iu) => add(p, mul(n, (2 * (iu / (nu - 1)) - 1) * hw(t))));
  });
  return grid(rows, { closed: false, seam: false, fibre: 'v', thick });
}

/** Ring rows from the inner to the outer edge (matching point lists). */
function ring(inner: readonly Vec2[], outer: readonly Vec2[], nv: number, closed: boolean, thick: number): Grid {
  const rows = Array.from({ length: nv }, (_, iv) => inner.map((p, i) => lerp(p, outer[i]!, iv / (nv - 1))));
  return grid(rows, { closed, seam: !closed, fibre: 'u', thick });
}

/** Ellipse arc around c (semi-axes a, b, rotated by rot) from angle t0 to t1, n points (y down). */
function arc(c: Vec2, a: number, b: number, rot: number, t0: number, t1: number, n: number): Vec2[] {
  const [cs, sn] = [Math.cos(rot), Math.sin(rot)];
  return Array.from({ length: n }, (_, k) => {
    const t = t0 + ((t1 - t0) * k) / (n - 1);
    const [x, y] = [a * Math.cos(t), b * Math.sin(t)];
    return { x: c.x + x * cs - y * sn, y: c.y + x * sn + y * cs };
  });
}

/** Muscle sheets of the patient's right side (outward = −x). */
export function rightSheets(F: readonly Vec2[]): Record<Anatomy, Grid[]> {
  const P = (i: number) => F[i]!;
  /** Offset outward (dx > 0 = towards the ear) and down. */
  const at = (p: Vec2, dx: number, dy: number): Vec2 => ({ x: p.x - dx, y: p.y + dy });

  // Frontalis: galea (top, the two bellies diverging upwards) → skin of the brow; lateral border on the temporal line.
  const brow = [at(P(70), 0.03, -0.01), at(P(63), 0, -0.02), at(P(105), 0, -0.02), at(P(66), 0, -0.02), at(P(107), 0, -0.02), at(P(107), -0.15, -0.01)];
  const up: [number, number][] = [
    [-0.11, -0.8],
    [-0.1, -0.84],
    [-0.06, -0.86],
    [0, -0.88],
    [0.06, -0.9],
    [0.16, -0.9],
  ];
  const galea = brow.map((p, k) => at(p, up[k]![0], up[k]![1]));
  const frontalis = sheet(galea, brow, 15, 12, 0.02);

  // Orbicularis oculi: palpebral part in the lids, orbital part out to the brow, the upper cheek and the lateral
  // orbital rim; medially at the frontal process beside the nose. Upper lid ↔ upper half of the outer ellipse.
  const eye = CONTOURS.rightEye.map(P); // 33 lateral → top → 133 medial → bottom → 33
  const iMed = CONTOURS.rightEye.indexOf(133);
  const eyeW = len(sub(P(133), P(33)));
  const oc = at(lerp(P(33), P(133), 0.5), 0.04, 0.02);
  const [ea, eb, tilt] = [0.93 * eyeW, 0.36, (-7 * Math.PI) / 180];
  const half = 28;
  const innerEye = [...resample(eye.slice(0, iMed + 1), half + 1).slice(0, -1), ...resample(eye.slice(iMed), half + 1).slice(0, -1)];
  const outerEye = [...arc(oc, ea, eb, tilt, Math.PI, 2 * Math.PI, half + 1).slice(0, -1), ...arc(oc, ea, eb, tilt, 2 * Math.PI, 3 * Math.PI, half + 1).slice(0, -1)];
  const orbOculi = ring(innerEye, outerEye, 10, true, 0.022);

  // Zygomaticus major: zygomatic body (below and lateral to the lateral canthus) → modiolus beside the mouth corner.
  const zo = at(P(117), 0.07, 0.06);
  const zi = at(P(61), 0.06, -0.03);
  const zm = lerp(zo, zi, 0.5);
  const zygMajor = strap(zo, at(zm, 0.03, 0.02), zi, (t) => 0.075 - 0.03 * t + 0.015 * Math.sin(Math.PI * t), 9, 16, 0.04);

  // Zygomaticus minor (zygomatic bone, medial to the major → lateral upper lip) and levator labii superioris
  // (infraorbital margin → upper lip between the ala and the corner, passing lateral to the ala).
  const zmo = at(P(118), 0.08, -0.02);
  const zmi = at(P(40), 0, -0.08);
  const zygMinor = strap(zmo, at(lerp(zmo, zmi, 0.5), 0.03, 0.02), zmi, (t) => 0.045 - 0.015 * t, 7, 14, 0.03);
  const lo = at(P(230), 0, 0.07);
  const li = at(lerp(P(39), P(40), 0.3), 0, -0.08);
  const lls = strap(lo, { x: lo.x + 0.08, y: 0.62 * li.y + 0.38 * lo.y + 0.03 }, li, (t) => 0.12 - 0.06 * t, 9, 14, 0.03);

  // Levator labii superioris alaeque nasi: frontal process of the maxilla beside the medial canthus → down the
  // side of the nose to the ala and the upper lip.
  const ao = at(P(193), 0.03, 0);
  const ai = at(P(64), 0.05, 0.08);
  const llsan = strap(ao, at(lerp(ao, ai, 0.5), 0.05, 0), ai, (t) => 0.025 + 0.035 * t * t, 7, 14, 0.025);

  // Levator anguli oris: canine fossa below the infraorbital foramen → modiolus; deep to the lip elevators.
  const lo2 = lerp(P(142), P(101), 0.55);
  const li2 = at(P(61), 0.07, -0.05);
  const lao = strap(lo2, at(lerp(lo2, li2, 0.5), 0.03, 0), li2, (t) => 0.05 - 0.02 * t, 7, 14, 0.03);

  // Corrugator supercilii: medial end of the brow ridge → skin above the middle of the brow, arching upwards.
  const co = at(lerp(P(8), P(55), 0.5), 0, -0.03);
  const ci = at(P(66), 0.02, -0.05);
  const corrugator = strap(co, at(lerp(co, ci, 0.5), 0, -0.04), ci, (t) => 0.028 + 0.018 * Math.sin(Math.PI * t) - 0.01 * t, 7, 12, 0.025);

  // Risorius: parotid and masseteric fascia at the side of the cheek → modiolus, a thin horizontal fan.
  const risorius = sheet(
    [lerp(P(58), P(61), 0.15), lerp(lerp(P(58), P(172), 0.5), P(61), 0.12), lerp(P(172), P(61), 0.1)],
    [at(P(61), 0.08, -0.03), at(P(61), 0.08, -0.01), at(P(61), 0.08, 0.01)],
    5,
    12,
    0.02,
  );

  // Buccinator (deep): the cheek wall from the front of the masseter to the modiolus, fibres horizontal.
  const buccinator = sheet(
    [at(lerp(P(61), P(58), 0.7), 0, -0.07), lerp(P(61), lerp(P(58), P(172), 0.5), 0.75), at(lerp(P(61), P(136), 0.7), 0, -0.03)],
    [at(P(61), 0.1, -0.1), at(P(61), 0.1, -0.01), at(P(61), 0.1, 0.08)],
    6,
    10,
    0.02,
  );

  // Platysma: lower face along the jaw → down the neck to the shoulder, the medial borders diverging below the chin;
  // fibres bend with the neck (control curve) so the sheet stays on it.
  const platysma = sheet(
    [
      { x: -0.66, y: 1.26 },
      { x: -0.52, y: 1.38 },
      { x: -0.38, y: 1.52 },
      { x: -0.24, y: 1.66 },
      { x: -0.1, y: 1.8 },
    ].map((p) => ({ x: p.x * (Math.abs(P(136).x) / 0.7), y: p.y })),
    [
      { x: -1.1, y: 2.18 },
      { x: -0.86, y: 2.18 },
      { x: -0.64, y: 2.18 },
      { x: -0.46, y: 2.18 },
      { x: -0.3, y: 2.18 },
    ],
    11,
    16,
    0.018,
    [
      { x: -0.52, y: 1.8 },
      { x: -0.44, y: 1.85 },
      { x: -0.34, y: 1.9 },
      { x: -0.24, y: 1.96 },
      { x: -0.16, y: 2.0 },
    ],
  );

  // Orbicularis oris (right half): vermilion border → nose base above, the modiolus laterally and the
  // mentolabial sulcus below; fibres run around the mouth.
  const lips = [0, 37, 39, 40, 185, 61, 146, 91, 181, 84, 17].map(P);
  const iCorner = 5;
  const m = lerp(P(13), P(14), 0.5);
  const top = m.y - (P(2).y + 0.02);
  const bot = P(18).y + 0.06 - m.y;
  const lat = Math.abs(P(61).x - m.x) + 0.13;
  const n2 = 16;
  const innerLip = [...resample(lips.slice(0, iCorner + 1), n2 + 1).slice(0, -1), ...resample(lips.slice(iCorner), n2 + 1)];
  const outerLip = [
    ...arc(m, lat, top, 0, -Math.PI / 2, -Math.PI, n2 + 1).slice(0, -1),
    ...arc(m, lat, bot, 0, -Math.PI, (-3 * Math.PI) / 2, n2 + 1),
  ];
  const orbOris = ring(innerLip, outerLip, 8, false, 0.035);

  // Depressor anguli oris: oblique line of the mandible → modiolus. Depressor labii inferioris: mandible between
  // the symphysis and the mental foramen → lower lip.
  const dao = sheet(
    [at(P(176), -0.02, -0.04), at(P(149), -0.01, -0.035), at(lerp(P(150), P(136), 0.4), -0.03, -0.03)],
    [at(P(61), 0.02, 0.03), at(P(61), 0.07, -0.01)],
    9,
    12,
    0.03,
  );
  const dli = sheet(
    [at(lerp(P(152), P(148), 0.5), 0, -0.07), at(lerp(P(148), P(176), 0.5), 0, -0.08), at(P(176), -0.03, -0.11)],
    [at(P(84), 0, 0.04), at(P(181), 0, 0.04), at(P(91), 0, 0.035)],
    8,
    10,
    0.025,
  );

  return {
    frontalis: [frontalis],
    corrugator: [corrugator],
    orbicularisOculi: [orbOculi],
    llsan: [llsan],
    lls: [lls],
    lao: [lao],
    zygMinor: [zygMinor],
    zygMajor: [zygMajor],
    risorius: [risorius],
    depressors: [dli, dao],
    orbicularisOris: [orbOris],
    platysma: [platysma],
    buccinator: [buccinator],
  };
}

const mirror = (g: Grid): Grid => ({ ...g, pts: g.pts.map((p) => ({ x: -p.x, y: p.y })) });

/** Sheets of one side (the left mirrors the right about the face's vertical axis). */
export function sideSheets(F: readonly Vec2[], side: 'left' | 'right'): Record<Anatomy, Grid[]> {
  const r = rightSheets(F);
  if (side === 'right') return r;
  return Object.fromEntries(Object.entries(r).map(([k, gs]) => [k, gs.map(mirror)])) as Record<Anatomy, Grid[]>;
}

/** Closed outline loops of a grid (a ring gives its outer and inner loop: fill with evenodd). */
export function outline(g: Grid): Vec2[][] {
  const at = (iu: number, iv: number) => g.pts[iv * g.nu + iu]!;
  const row = (iv: number) => Array.from({ length: g.nu }, (_, iu) => at(iu, iv));
  if (g.closed) return [row(g.nv - 1), row(0)];
  const col = (iu: number) => Array.from({ length: g.nv }, (_, iv) => at(iu, iv));
  return [[...row(0), ...col(g.nu - 1).slice(1), ...row(g.nv - 1).reverse().slice(1), ...col(0).reverse().slice(1, -1)]];
}
