/** Exercises aimed at co-movement of each region (see planner synkinesis programme). */
export const FOR_REGION: Record<CouplingRegion, string[]> = {
  eye: ['dissoc-smile-eye', 'eye-open', 'orbicularis-sweep'],
  mouth: ['dissoc-eye-mouth', 'zygomatic-lift', 'corner-lift'],
  brow: ['brow-relax', 'frontalis-lift'],
  midface: ['levator-labii', 'massage-cheek'],
  upperLip: ['dissoc-eye-mouth', 'levator-labii'],
};

export function describe(r: CouplingResult, e: CouplingExpression, g: CouplingRegion): string {
  const c = r.cells[e]![g];
  const how =
    g === 'eye'
      ? `${Math.round(c.excess * 100)}% 더 작아집니다`
      : `${r.mmPerUnit ? `${(c.excess * r.mmPerUnit).toFixed(1)} mm` : '조금'} 더 움직입니다`;
  return `${WHEN[e]} 마비 쪽 ${REGION_SUBJ[g]} 건강한 쪽보다 ${how}`;
}

/** Region severity (excess / threshold) of flagged or mild cells, for one expression or the worst over all. */
export function synkValues(
  r: CouplingResult,
  only: CouplingExpression | 'all',
): { v: RegionValues; worst: Partial<Record<CouplingRegion, CouplingExpression>> } {
  const v: RegionValues = {};
  const worst: Partial<Record<CouplingRegion, CouplingExpression>> = {};
  for (const e of COUPLING_EXPRESSIONS) {
    if (only !== 'all' && e !== only) continue;
    for (const g of COUPLING_REGIONS) {
      const c = r.cells[e]?.[g];
      if (!c || !(c.flagged || c.mild)) continue;
      const sev = c.excess / COUPLING_THRESHOLDS[g];
      if (sev > (v[g] ?? 0)) [v[g], worst[g]] = [sev, e];
    }
  }
  return { v, worst };
}

/** Face map card: synkinesis per region (darker = stronger), or weakness from the latest assessment. */
export function FaceMapCard({
  r,
  analysis,
}: {
  r: CouplingResult;
  /** Weakness source (the assessment captured together); defaults to the latest assessment. */
  analysis?: AnalysisResult;
}) {
  const { sessions } = useApp();
  const [tab, setTab] = useState<'synk' | 'weak'>('synk');
  const [only, setOnly] = useState<CouplingExpression | 'all'>('all');
  const [sel, setSel] = useState<CouplingRegion | null>(null);
  const withAny = COUPLING_EXPRESSIONS.filter((e) => COUPLING_REGIONS.some((g) => r.cells[e]?.[g]?.flagged || r.cells[e]?.[g]?.mild));
  const latest = [...sessions].reverse().find((x) => x.analysis.tasks && Object.keys(x.analysis.tasks).length);
  const last = analysis ? { analysis, createdAt: null } : latest;
  const ratio = (t: 'brow' | 'eyeClose' | 'smile' | 'snarl') => last?.analysis.tasks[t]?.ratio ?? null;
  const weakOf: Record<CouplingRegion, number | null> = {
    brow: ratio('brow'),
    eye: ratio('eyeClose'),
    midface: ratio('snarl'),
    upperLip: ratio('smile'),
    mouth: ratio('smile'),
  };
  const sk = synkValues(r, only);
  // Colour scale: mild (0.5) is light, three times the threshold or more is darkest.
  const values: RegionValues =
    tab === 'synk'
      ? Object.fromEntries(Object.entries(sk.v).map(([g, x]) => [g, Math.min(1, x / 3)]))
      : Object.fromEntries(COUPLING_REGIONS.flatMap((g) => (weakOf[g] == null ? [] : [[g, 1 - Math.max(0, Math.min(1, weakOf[g]!))]])));
  const top = (Object.entries(sk.v) as [CouplingRegion, number][]).sort((a, b) => b[1] - a[1])[0];
  const info = (g: CouplingRegion): string => {
    if (tab === 'weak') {
      const x = weakOf[g];
      if (x == null) return `${REGION_NAME[g]}: 최근 평가에 값이 없습니다.`;
      const v = ratioView(x);
      return v.kind === 'pct' ? `${REGION_NAME[g]}: 마비 쪽 움직임이 건강한 쪽의 ${v.text}` : `${REGION_NAME[g]}: ${v.text} — ${v.note}`;
    }
    const e = sk.worst[g];
    return e ? `${describe(r, e, g)}${r.cells[e]![g].mild ? ' (미세)' : ''}.` : `${REGION_NAME[g]}: 함께 움직임이 보이지 않았습니다.`;
  };
  return (
    <div class="card">
      <div class="row" style={{ gap: '6px', marginBottom: '8px' }}>
        <button class={`btn sm ${tab === 'synk' ? 'primary' : ''}`} onClick={() => setTab('synk')}>
          연합운동
        </button>
        <button class={`btn sm ${tab === 'weak' ? 'primary' : ''}`} onClick={() => setTab('weak')} disabled={!last}>
          마비 정도
        </button>
      </div>
      {tab === 'synk' && withAny.length > 0 && (
        <div class="row wrap" style={{ gap: '4px', marginBottom: '6px' }}>
          {(['all', ...withAny] as const).map((e) => (
            <button class={`btn sm ${only === e ? '' : 'ghost'}`} onClick={() => setOnly(e)}>
              {e === 'all' ? '전체' : LABEL[e]}
            </button>
          ))}
        </div>
      )}
      <FaceMap
        affectedSide={r.affectedSide}
        values={values}
        tone={tab === 'synk' ? 'synk' : 'weak'}
        selected={sel}
        onSelect={(g) => setSel(g === 'lowerLip' ? null : g)}
      />
      <p class="small" style={{ minHeight: '2.6em' }}>
        {sel
          ? info(sel)
          : tab === 'synk'
            ? top
              ? `가장 두드러진 곳: ${info(top[0])}`
              : '함께 움직이는 곳이 없습니다.'
            : last
              ? '색이 진할수록 마비 쪽 움직임이 약합니다. 부위를 누르면 값이 보입니다.'
              : '평가 기록이 없습니다.'}
      </p>
      <p class="xsmall muted">
        {tab === 'synk'
          ? '색이 진할수록 마비 쪽이 더 많이 따라 움직입니다(연한색 = 미세, 가장 진한색 = 기준의 3배 이상). 부위를 누르면 설명이 보입니다.'
          : `${last?.createdAt ? `최근 얼굴 평가(${fmtDate(last.createdAt)})` : '이번 평가'} 기준. 윗입술·입꼬리는 미소, 코·볼은 코 찡그리기 값입니다.`}
      </p>
    </div>
  );
}
